<?php
session_start(); require_once '../middleware/student.php'; require_once '../config/database.php'; require_once '../helpers/csrf_helper.php'; require_once '../helpers/alert_response_helper.php';
function restartResponseLetterAlert(string $alert): never {
    header('Location: response_letter.php?restart_alert='.rawurlencode($alert));
    exit;
}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: response_letter.php');exit;} verify_csrf_or_abort();
$reason=(string)($_POST['restart_reason']??'rejected'); if(!in_array($reason,['rejected','relocation'],true)){restartResponseLetterAlert('invalid');}
$sql=$reason==='relocation'
    ? 'SELECT ip.internship_profile_id,ip.student_id,ia.document_id FROM internship_profile ip JOIN student s ON s.student_id=ip.student_id JOIN internship_application ia ON ia.internship_profile_id=ip.internship_profile_id JOIN internship_response_document rd ON rd.internship_profile_id=ip.internship_profile_id AND rd.review_status="approved" JOIN internship_tracking it ON it.internship_profile_id=ip.internship_profile_id AND it.send_letter_status="sent" WHERE s.user_id=? AND ip.request_status="active" LIMIT 1'
    : 'SELECT ip.internship_profile_id,ip.student_id,ia.document_id FROM internship_profile ip JOIN student s ON s.student_id=ip.student_id JOIN internship_application ia ON ia.internship_profile_id=ip.internship_profile_id JOIN internship_response_document rd ON rd.internship_profile_id=ip.internship_profile_id AND rd.review_status="not_accepted" WHERE s.user_id=? AND ip.request_status="active" LIMIT 1';
$stmt=$pdo->prepare($sql);$stmt->execute([$_SESSION['user_id']]);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row){restartResponseLetterAlert($reason==='relocation'?'relocation_not_ready':'rejected_not_ready');}
$closedReason=$reason==='relocation'?'ย้ายที่ฝึกงาน':'สถานประกอบการไม่รับเข้าฝึกงาน';$reasonValue=$reason==='relocation'?'relocation':'not_accepted';$detail=$reason==='relocation'?'ปิดคำร้องเดิมเนื่องจากย้ายที่ฝึกงาน และเริ่มคำร้องฉบับใหม่':'ปิดคำร้องสหกิจฉบับนี้หลังสถานประกอบการไม่รับเข้าฝึกงาน และเริ่มคำร้องฉบับใหม่';
$pdo->beginTransaction();try{$pdo->prepare('UPDATE internship_profile SET request_status="closed",closed_reason=?,closed_at=NOW() WHERE internship_profile_id=?')->execute([$closedReason,$row['internship_profile_id']]);$pdo->prepare('INSERT INTO internship_profile (student_id,request_status,request_reason,previous_profile_id,company_name) VALUES (?,"active",?,?,"")')->execute([$row['student_id'],$reasonValue,$row['internship_profile_id']]);$pdo->prepare('INSERT INTO document_events(document_id,actor_user_id,event_type,detail) VALUES (?,? ,"restart",?)')->execute([$row['document_id'],$_SESSION['user_id'],$detail]);$pdo->commit();restartResponseLetterAlert($reason==='relocation'?'relocation_complete':'rejected_complete');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Restart internship request failed: '.$e->getMessage());restartResponseLetterAlert('failed');}
